package yom.yomSprint;import org.bukkit.Bukkit;import org.bukkit.Location;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import yom.yomSprint.commands.managers.CommandExecutorBase;import yom.yomSprint.commands.managers.CommandsManager;import yom.yomSprint.configurations.MessagesConfiguration;import yom.yomSprint.configurations.PlayersConfiguration;import yom.yomSprint.configurations.TracksConfiguration;import yom.yomSprint.database.DatabaseAdapter;import yom.yomSprint.database.DatabaseManager;import yom.yomSprint.listeners.*;import yom.yomSprint.managers.SpectatorManager;import yom.yomSprint.managers.CompetitionManager;import yom.yomSprint.models.*;import yom.yomSprint.managers.ChatInputManager;import yom.yomSprint.utils.CustomMessage;import yom.yomSprint.utils.PlaceholderSprint;import yom.yomSprint.utils.Replacer;import java.io.File;import java.util.*;public final class YomSprint extends JavaPlugin {    private TracksConfiguration tracksConfiguration;    private MessagesConfiguration messagesConfiguration;    private CommandsManager commandsManager;    private CommandExecutorBase base;    private Location lobbyLocation;    private HashMap<UUID, PlayersConfiguration> playersConfigsMap;    private SpectatorManager spectatorManager;    private CompetitionManager competitionManager;    private ChatInputManager chatInputManager;    private DatabaseManager databaseManager;    private DatabaseAdapter databaseAdapter;    @Override    public void onEnable() {        this.loadDefaultConfigs();        this.competitionManager = new CompetitionManager(this);        this.tracksConfiguration = new TracksConfiguration(this);        this.messagesConfiguration = new MessagesConfiguration(this);        this.spectatorManager = new SpectatorManager(this);        this.chatInputManager = new ChatInputManager();        this.databaseManager = new DatabaseManager(this);        File file = new File(getDataFolder().getAbsolutePath()+File.separator+"players");        if (!file.exists()){            file.mkdir();        }        playersConfigsMap = new HashMap<>();        loadListeners();        if(isMainLobbyValid()) {            loadTracks();            lobbyLocation = getConfig().getLocation("config.main_lobby");        }else {            System.out.println(CustomMessage.ANSI_RED + "Defina o main lobby para carregar as pistas" + CustomMessage.ANSI_RESET);        }        base = new CommandExecutorBase(this);        getCommand("run").setExecutor(base);        commandsManager = new CommandsManager(this);        if (Bukkit.getPluginManager().getPlugin("PlaceholderAPI") != null){            new PlaceholderSprint(this).register();        }        this.databaseAdapter = databaseManager.getAdapter(getConfig().getString("config.database_type"));;        this.databaseAdapter.initialize();    }    @Override    public void onDisable() {        for (Competition competition : competitionManager.getCompetitions()) {            for (Runner runner : competition.getRunners()) {                Player player = Bukkit.getPlayer(runner.getUuid());                Track track = competition.getTrack();                player.setInvulnerable(false);                runner.deleteBoard(runner.getWaitBoard());                runner.deleteBoard(runner.getCompetitionBoard());                if (isMainLobbyValid()) {                    player.teleport(lobbyLocation);                }            }        }    }    private void loadTracks() {        Set<String> tracks = tracksConfiguration.getConfig().getConfigurationSection("tracks").getKeys(false);        for (String key : tracks) {            List<Lane> lanes = new ArrayList<>();            int lanesCount = 1;            if (tracksConfiguration.getConfig().contains("tracks." + key + ".lanes")) {                for(String string : tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getKeys(false)){                    Location startLocation1 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".startPos1");                    Location startLocation2 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".startPos2");                    BoudingBox startBoudingBox = new BoudingBox(startLocation1,startLocation2);                    Location endLocation1 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".endPos1");                    Location endLocation2 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".endPos2");                    BoudingBox endBoudingBox = new BoudingBox(endLocation1,endLocation2);                    Location edge1 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".edgePos1");                    Location edge2 = tracksConfiguration.getConfig().getConfigurationSection("tracks." + key + ".lanes").getLocation(lanesCount + ".edgePos2");                    lanes.add(new Lane(startBoudingBox,endBoudingBox,edge1,edge2,lanesCount));                    lanesCount++;                }            }            Iterator<Lane> iterator = lanes.iterator();            while (iterator.hasNext()){                Lane lane = iterator.next();                if (!getCompetitionManager().isValidLane(lane)){                    iterator.remove();                }            }            Track track = new Track.TrackBuilder()                    .setName(key)                    .setDisplayName(tracksConfiguration.getConfig().getString("tracks." + key + ".display_name"))                    .setMinSize(tracksConfiguration.getConfig().getInt("tracks." + key + ".min_players"))                    .setMaxSize(tracksConfiguration.getConfig().getInt("tracks." + key + ".max_players"))                    .setLanes(lanes)                    .setPlugin(this)                    .build();            track.loadConfigs();            this.competitionManager.getTracks().add(track);            if (track.hasAllConfigs()) {                List<String> waitLobbyScoreboad = getMessagesConfiguration().getConfig().getStringList("scoreboards.waitLobbyScoreboard");                List<String> gameScoreboard = getMessagesConfiguration().getConfig().getStringList("scoreboards.gameScoreboard");                String waitLobbyScoreboardTittle = getMessagesConfiguration().getConfig().getString("scoreboards.waitLobbyScoreboardTittle");                String competitionScoreboardTittle = getMessagesConfiguration().getConfig().getString("scoreboards.gameScoreboardTittle");                Competition competition = new Competition(this,track);                this.competitionManager.addGame(competition);            }        }    }    private void loadListeners(){        getServer().getPluginManager().registerEvents(new MainGUIListener(this), this);        getServer().getPluginManager().registerEvents(new ChooseGameGUIListener(this), this);        getServer().getPluginManager().registerEvents(new PlayerQuitListener(this), this);        getServer().getPluginManager().registerEvents(new PlayerJoinListener(this), this);        getServer().getPluginManager().registerEvents(new PlayerMoveListener(this),this);        getServer().getPluginManager().registerEvents(new PlayerInteractListener(this),this);        getServer().getPluginManager().registerEvents(new PlayerChatListener(this),this);        getServer().getPluginManager().registerEvents(new ChoosePositionsGUIListener(this),this);        getServer().getPluginManager().registerEvents(new PlayerClickListener(this),this);    }    public boolean isMainLobbyValid(){        Object obj = getConfig().get("config.main_lobby");        if (!(obj instanceof Location)) {            getLogger().warning("A chave 'main_lobby' não é uma Location válida!");            return false;        }        return true;    }    public DatabaseAdapter getDatabaseAdapter() {        return databaseAdapter;    }    public DatabaseManager getDatabaseManager() {        return databaseManager;    }    private void loadDefaultConfigs() {        saveDefaultConfig();    }    public CommandExecutorBase getBase() {        return base;    }    public CommandsManager getCommandsManager() {        return commandsManager;    }    public Location getLobbyLocation() {        return lobbyLocation;    }    public void setLobbyLocation(Location lobbyLocation){        this.lobbyLocation = lobbyLocation;    }    public MessagesConfiguration getMessagesConfiguration() {        return messagesConfiguration;    }    public TracksConfiguration getTracksConfiguration() {        return tracksConfiguration;    }    public HashMap<UUID, PlayersConfiguration> getPlayersConfigsMap() {        return playersConfigsMap;    }    public SpectatorManager getSpectatorManager() {        return spectatorManager;    }    public ChatInputManager getChatInputManager() {        return chatInputManager;    }    public CompetitionManager getCompetitionManager() {        return competitionManager;    }}